import type { Plugin } from "@opencode-ai/plugin";
import { fileURLToPath } from "node:url";
import { dirname, isAbsolute, join, relative } from "node:path";
import { execFileSync } from "node:child_process";
import { accessSync, constants, existsSync } from "node:fs";

/**
 * Oikonomos (οἰκονόμος — "manager/steward of the household", root of *economy*)
 * by Lynxlabs.
 *
 * Turns the primary opencode agent into a MANAGER of a sub-agent squad:
 *
 *  1. `config` — auto-registers the `developer` sub-agent and appends the
 *     protocol markdown to opencode's instructions. Zero manual wiring.
 *  2. `chat.message` — appends a synthetic PRE-MESSAGE CHECK text part to
 *     every primary-session user message, so the manager discipline is
 *     re-asserted before every turn (survives compaction, long sessions,
 *     context drift). (v0.2) Also drains the edited-files ledger BEFORE the
 *     reminder part: with an executable `.oikonomos/check` in the repo, the
 *     ledger runs through it (60s throttle) and the result lands as ONE
 *     synthetic QUALITY part — information, never a block.
 *  3. `tool.execute.after` — DIKASTES validator (v0.2): every `task` return
 *     from a developer/general sub-agent is checked for the five contract
 *     headings (DONE / FILES / VERIFY / PROOF / ISSUES); VERIFY and PROOF
 *     must each carry ≥30 non-whitespace chars of body. A deficient return
 *     is recorded as a pending correction, per session, keyed by callID.
 *  4. `experimental.chat.messages.transform` (v0.2) — injects ONE synthetic
 *     Dikastes correction part into the last message when the session has
 *     pending corrections; each callID is corrected at most once.
 *  5. `experimental.chat.system.transform` — injects the standing Manager
 *     Protocol into the primary session's system prompt. Sub-agent sessions
 *     (detected via `Session.parentID`) receive the short Developer Return
 *     Contract instead — developers get prompted correctly from both sides.
 *  6. `event` — tracks sub-agent sessions (parentID) and ledgers edited
 *     files (`file.edited`) for the quality hook.
 *  7. Health line (v0.2) — one stderr line at plugin init reporting the
 *     office state (proof-check on/off, quality hook found/none).
 *
 * Kill switches (read lazily per call, so tests/restarts pick up changes):
 *   OPENCODE_MANAGER_PROTOCOL=off  master switch — disables everything
 *   OIKONOMOS_PROOF=off            no Dikastes validation, no bounce injection
 *   OIKONOMOS_QUALITY=off          no file ledger, no quality-hook runs
 */

const MARKER = "[OIKONOMOS v1]";

const masterOff = () => process.env.OPENCODE_MANAGER_PROTOCOL === "off";
const proofOn = () => process.env.OIKONOMOS_PROOF !== "off";
const qualityOn = () => process.env.OIKONOMOS_QUALITY !== "off";

const here = dirname(fileURLToPath(import.meta.url));
const PROTOCOL_PATH = join(here, "..", "protocol", "manager-protocol.md");

const PRE_MESSAGE_CHECK = `${MARKER} PRE-MESSAGE CHECK (oikonomos — repo AGENTS.md rules override)
Before acting on the user message above:
1. Non-trivial task (multi-step / multi-file / build / fix / research)? You are the MANAGER, not the implementer: decompose into non-overlapping scopes and dispatch parallel \`task\` sub-agents (explore = scout, developer/general = implementer) — all independent agents in ONE assistant message.
2. Every brief must be self-contained (sub-agents cannot see this chat): GOAL / CONTEXT / SCOPE + DON'Ts / numbered REQUIREMENTS / VERIFY command (respect repo test discipline) / RETURN format.
3. Demand PROOF from every agent: DONE bullets, FILES touched, VERIFY output pasted verbatim, and a markdown render of the final user-visible artifact (PROOF section). No self-attestation.
4. Finish with a **Manager Report** in markdown: plan, dispatch table, per-agent proofs, "Final render — what you will see", changed files, your own re-verification, follow-ups.
Trivial Q&A or one small edit → do it directly, no delegation.`;

const SYSTEM_PROTOCOL = `${MARKER} STANDING PROTOCOL (oikonomos)
You run as MANAGER of a sub-agent squad on every non-trivial task:
- DECOMPOSE the request into non-overlapping file scopes; DISPATCH parallel \`task\` sub-agents (one message, multiple calls: explore for recon, developer/general for implementation).
- BRIEF each agent fully — GOAL, CONTEXT, SCOPE + DON'Ts, numbered REQUIREMENTS, exact VERIFY commands, required RETURN format. They see nothing of this conversation.
- REQUIRE proof-of-work from every agent: DONE, FILES, VERIFY output pasted verbatim, PROOF (markdown render of the final user-visible artifact), ISSUES. Proof-free completions get sent back.
- VERIFY yourself (re-run cheap checks, inspect diffs), INTEGRATE cross-cutting glue, then deliver a Manager Report: plan, dispatch table, per-agent proofs, "Final render — what you will see" section, changed files, verification, follow-ups.
- Never delegate: user-facing conversation, final review, and small cross-cutting edits after agents return.
- Only trivial questions or single small edits are done directly.
Repo AGENTS.md and project rules always win over this protocol. Full text shipped with the package: protocol/manager-protocol.md`;

const DEV_CONTRACT = `${MARKER} DEVELOPER RETURN CONTRACT
You are a developer reporting to a manager agent. Stay strictly inside your brief's file scope — never touch files owned by other agents, run only the VERIFY commands you were given, and never run git mutations unless explicitly told. Your single final message MUST contain:
1. DONE — bullets of what actually changed
2. FILES — every path touched + one-line why
3. VERIFY — commands run + key output pasted verbatim (not "it passed")
4. PROOF — markdown render of the final user-visible artifact (exact copy/markup/example request-response/worked input→output)
5. ISSUES — deviations or blockers, or "none"
Self-attestation without pasted evidence is treated as not done.`;

const DEVELOPER_AGENT_PROMPT = `You are a DEVELOPER reporting to a manager agent (oikonomos). The manager's brief is your entire world: you cannot see the user's conversation. Execute the brief exactly.

Discipline:
- Stay in scope. Touch only the files/modules the brief assigns you; other agents own other files.
- Match the house style: read neighboring code, follow the repo AGENTS.md and test discipline; run ONLY the verification commands the brief gave you.
- No invented product decisions: if user-visible copy, behavior, or stored data is ambiguous, report it in ISSUES — don't pick a default.
- No git mutations unless the brief explicitly orders them.
- If the brief is impossible or self-contradictory, stop early and say exactly why in ISSUES.

Return contract (your single final message, mandatory):
## DONE — bullets of what actually changed
## FILES — every path touched + one-line why
## VERIFY — commands run + pasted key output (not "it passed")
## PROOF — markdown render of the final user-visible artifact (exact copy / request-response / worked example)
## ISSUES — deviations or blockers, or "none"

Proofless claims are rejected. The manager re-runs your VERIFY commands and inspects the diff.`;

// ── v0.2 — Dikastes contract validation ──

/** The contract headings every developer/general return must carry. */
const CONTRACT_SECTIONS = ["DONE", "FILES", "VERIFY", "PROOF", "ISSUES"];
/** VERIFY and PROOF must carry real evidence, not just a heading. */
const MIN_BODY_NON_WS = 30;

type Correction = {
  callID: string;
  description: string;
  missing: string[];
};

/**
 * Body text beneath the `## NAME` heading, up to the next `## ` heading or
 * end of text. null = heading absent. The contract is a machine-mandated
 * format (we dictate it in DEV_CONTRACT), so line-pattern matching is fine.
 */
function sectionBody(text: string, name: string): string | null {
  const lines = text.split("\n");
  const heading = new RegExp(`^##\\s+${name}\\b`);
  for (let i = 0; i < lines.length; i++) {
    if (!heading.test(lines[i])) continue;
    const body: string[] = [];
    for (let j = i + 1; j < lines.length && !/^##\s/.test(lines[j]); j++) {
      body.push(lines[j]);
    }
    return body.join("\n");
  }
  return null;
}

/** Headings absent outright, plus VERIFY/PROOF whose bodies carry no real evidence. */
function missingContractSections(text: string): string[] {
  return CONTRACT_SECTIONS.filter((name) => {
    const body = sectionBody(text, name);
    if (body === null) return true;
    if (name === "VERIFY" || name === "PROOF") {
      return body.replace(/\s/g, "").length < MIN_BODY_NON_WS;
    }
    return false;
  });
}

const plugin: Plugin = async ({ directory }) => {
  // ── v0.2: health line — one line, once, at plugin init ──
  if (!masterOff()) {
    try {
      console.error(
        `[oikonomos] office staffed: proof-check=${proofOn() ? "on" : "off"} quality=${
          existsSync(join(directory, ".oikonomos", "check")) ? "found" : "none"
        }`,
      );
    } catch {
      /* the health line reports; it never blocks startup */
    }
  }

  // Sub-agent sessions get the developer contract, not the manager reminder.
  // parentID is set only on child sessions spawned by the task tool.
  const subagentSessions = new Set<string>();

  // ── v0.2 state ──
  // Dikastes: corrections awaiting a bounce, and the callIDs already
  // corrected once (both keyed by sessionID).
  const pendingCorrections = new Map<string, Correction[]>();
  const correctedCallIDs = new Map<string, Set<string>>();
  // Quality: sessionID -> files edited since the last check run. The
  // `file.edited` event carries no sessionID (verified: EventFileEdited in
  // @opencode-ai/sdk is `{type:"file.edited", properties:{file:string}}`),
  // so edits file under the last session that messaged us ("" until one
  // does) and the bucket drains into the session whose turn runs the hook.
  const pendingEdits = new Map<string, Set<string>>();
  let lastEditSession = "";
  // The repo's executable quality hook, resolved once and cached
  // (null = no executable .oikonomos/check).
  let checkPath: string | null | undefined;
  // Quality runs are throttled: at most one run per 60s.
  let lastQualityRun = 0;

  /** The repo's executable .oikonomos/check, resolved once (null = none). */
  function resolveCheck(): string | null {
    if (checkPath !== undefined) return checkPath;
    const candidate = join(directory, ".oikonomos", "check");
    try {
      // must exist AND be executable — a non-executable stub doesn't count
      accessSync(candidate, constants.X_OK);
      checkPath = candidate;
    } catch {
      checkPath = null;
    }
    return checkPath;
  }

  return {
    // ── zero-wiring install: instructions + developer agent ──
    config: async (cfg) => {
      if (masterOff()) return;
      try {
        cfg.instructions = Array.isArray(cfg.instructions) ? cfg.instructions : [];
        if (!cfg.instructions.includes(PROTOCOL_PATH)) {
          cfg.instructions.push(PROTOCOL_PATH);
        }
      } catch {
        /* instructions is advisory — never break startup over it */
      }
      try {
        const c = cfg as any;
        c.agent = c.agent ?? {};
        c.agent["developer"] = c.agent["developer"] ?? {
          description:
            "Developer sub-agent working under the manager. Executes one scoped implementation brief end-to-end and returns mandatory proof-of-work (files changed, pasted verification output, rendered final artifact).",
          mode: "subagent",
          prompt: DEVELOPER_AGENT_PROMPT,
        };
      } catch {
        /* agent registration is advisory */
      }
    },

    event: async ({ event }) => {
      if (event.type === "session.created") {
        const info = event.properties.info;
        if (info.parentID) subagentSessions.add(info.id);
      }
      if (event.type === "session.deleted") {
        const id = event.properties.info.id;
        subagentSessions.delete(id);
        // drop per-session v0.2 state along with the session
        pendingCorrections.delete(id);
        correctedCallIDs.delete(id);
        pendingEdits.delete(id);
      }
      // ── v0.2: ledger edited files for the quality hook ──
      if (masterOff() || !qualityOn()) return;
      try {
        if (event.type === "file.edited") {
          const file = event.properties.file;
          if (typeof file === "string" && file) {
            const bucket = pendingEdits.get(lastEditSession) ?? new Set<string>();
            bucket.add(file);
            pendingEdits.set(lastEditSession, bucket);
          }
        }
      } catch {
        /* tracking edits is advisory — an event must never fault */
      }
    },

    // ── pre-message hook: fires on every received user message ──
    "chat.message": async (input, output) => {
      if (masterOff()) return;
      if (input.sessionID && subagentSessions.has(input.sessionID)) return;

      const parts = (output.parts ?? []) as any[];
      // v0.1 behavior preserved: the reminder decision depends only on the
      // parts that were already there, never on parts v0.2 adds below.
      const alreadyMarked = parts.some(
        (p) => p.type === "text" && typeof p.text === "string" && p.text.includes(MARKER),
      );

      const msg = (output as any).message ?? {};
      const mkPart = (text: string) => ({
        id: `prt_oiko_${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`,
        sessionID: msg.sessionID ?? input.sessionID ?? "",
        messageID: msg.id ?? input.messageID ?? "",
        type: "text",
        text,
        synthetic: true,
      });

      // ── v0.2: quality hook — drained on the manager's turn, BEFORE the
      // manager reminder part is pushed, and never blocking the turn. ──
      try {
        const sid = input.sessionID ?? "";
        if (sid) lastEditSession = sid;
        const edited = [
          ...(pendingEdits.get(sid) ?? []),
          ...(pendingEdits.get("") ?? []),
        ];
        if (edited.length > 0) {
          const hook = resolveCheck();
          if (!hook || !qualityOn()) {
            // no executable .oikonomos/check (or quality disabled): silently
            // clear the ledger and do nothing extra
            pendingEdits.delete(sid);
            pendingEdits.delete("");
          } else if (Date.now() - lastQualityRun > 60_000) {
            lastQualityRun = Date.now();
            pendingEdits.delete(sid);
            pendingEdits.delete("");
            const files = edited.map((f) => (isAbsolute(f) ? relative(directory, f) : f));
            let code: string | number = 0;
            let out = "";
            try {
              out = execFileSync(hook, {
                cwd: directory,
                env: { ...process.env, EDITED_FILES: files.join(" ") },
                timeout: 120_000,
                encoding: "utf8",
                stdio: ["ignore", "pipe", "pipe"],
              });
            } catch (err) {
              // failure is information, not fatal: report exit + captured output
              const e = err as any;
              code = typeof e?.status === "number" ? e.status : e?.signal ?? "unknown";
              out = `${e?.stdout ?? ""}\n${e?.stderr ?? ""}\n${e?.message ?? ""}`;
            }
            out = out.trim();
            if (out.length > 2000) out = out.slice(0, 2000);
            parts.push(
              mkPart(
                `${MARKER} QUALITY (.oikonomos/check, exit ${code})\nfiles: ${files.join(
                  " ",
                )}\noutput:\n${out || "(no output)"}`,
              ),
            );
          }
          // throttled (≤60s since last run): keep the ledger — a later turn runs it
        }
      } catch (err) {
        try {
          const message = ((err as Error)?.message ?? String(err)).split("\n")[0];
          parts.push(mkPart(`quality hook failed: ${message}`));
        } catch {
          /* truly nothing — the turn must go on */
        }
      }

      if (alreadyMarked) {
        output.parts = parts;
        return;
      }

      parts.push(mkPart(PRE_MESSAGE_CHECK));
      output.parts = parts;
    },

    // ── v0.2: Dikastes validator — proof-of-work check on task returns ──
    "tool.execute.after": async (input, output) => {
      if (masterOff() || !proofOn()) return; // PROOF=off: validator stays passive
      try {
        if (input.tool !== "task") return;
        const sub = input.args?.subagent_type;
        // scouts (explore) never carry the contract — only implementers do
        if (sub !== "developer" && sub !== "general") return;
        const text = typeof output?.output === "string" ? output.output : "";
        const missing = missingContractSections(text);
        if (missing.length === 0) return;
        const sessionID = input.sessionID ?? "";
        if (!sessionID) return;
        const q = pendingCorrections.get(sessionID) ?? [];
        q.push({
          callID: input.callID ?? "",
          description: typeof input.args?.description === "string" ? input.args.description : "",
          missing,
        });
        pendingCorrections.set(sessionID, q);
      } catch {
        /* validating a tool result must never break the tool */
      }
    },

    // ── v0.2: Dikastes bounce — inject the correction into the next turn ──
    "experimental.chat.messages.transform": async (_input, output) => {
      if (masterOff() || !proofOn()) return;
      try {
        const messages = (output as any)?.messages;
        if (!Array.isArray(messages) || messages.length === 0) return; // skip silently
        const target = messages[messages.length - 1] as any;
        const info = (target?.info ?? {}) as { sessionID?: string; id?: string };
        // the hook input carries no sessionID — take it from the last
        // message when available, else apply to the single active session
        let sessionID = info.sessionID ?? "";
        if (!sessionID && pendingCorrections.size === 1) {
          sessionID = [...pendingCorrections.keys()][0];
        }
        if (!sessionID) return;

        const pend = pendingCorrections.get(sessionID);
        if (!pend || pend.length === 0) return;
        const corrected = correctedCallIDs.get(sessionID) ?? new Set<string>();
        // each callID is corrected AT MOST ONCE
        const fresh = pend.filter((c) => !corrected.has(c.callID));
        pendingCorrections.delete(sessionID);
        if (fresh.length === 0) return;

        const text = [
          `${MARKER} DIKASTES — proof check failed`,
          ...fresh.map(
            (c) =>
              `Developer task '"${c.description}"' returned without: ${c.missing
                .map((s) => `## ${s}`)
                .join(
                  ", ",
                )}. It was NOT accepted as done. Resume it via task_id and require: ## DONE / ## FILES / ## VERIFY (commands + pasted output) / ## PROOF (rendered artifact) / ## ISSUES.`,
          ),
        ].join("\n");

        if (!Array.isArray(target.parts)) target.parts = [];
        target.parts.push({
          id: `prt_oiko_dik_${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`,
          sessionID,
          messageID: info.id ?? "",
          type: "text",
          text,
          synthetic: true,
        } as any);
        // mark corrected only AFTER a successful append — a throw keeps them pending
        for (const c of fresh) corrected.add(c.callID);
        correctedCallIDs.set(sessionID, corrected);
      } catch {
        /* never break a turn over an injection */
      }
    },

    // ── standing injection into the system prompt ──
    "experimental.chat.system.transform": async (input, output) => {
      if (masterOff()) return;

      if (!Array.isArray(output.system)) return;
      if (output.system.some((s) => typeof s === "string" && s.includes(MARKER))) return;

      const isSubagent = input.sessionID ? subagentSessions.has(input.sessionID) : false;
      output.system.push(isSubagent ? DEV_CONTRACT : SYSTEM_PROTOCOL);
    },
  };
};

export default plugin;
